structureCode.vanilla:
const corpo = document.createElement('div');
corpo.textContent = 'conteúdo principal';

const rodape = document.createElement('div');
rodape.className = 'nds-cluster';
rodape.dataset.spacing = 'sm';
rodape.append(
  createButton({ variant: 'outline', label: 'Cancelar' }),
  createButton({ label: 'Aplicar' }),
);

const sheet = createSheet({
  trigger: createButton({ variant: 'outline', label: 'Abrir' }),
  side: 'right',
  title: 'Título',
  description: 'Descrição obrigatória.',
  content: corpo,
  footer: rodape,
});

extensibilityCode.vanilla:
// Painel controlado por estado externo
const sheet = createSheet({
  trigger: createButton({ variant: 'outline', label: 'Filtros' }),
  side: 'right',
  class: 'painel-largo',
  title: 'Filtros avançados',
  description: 'Refine os resultados.',
  content: buildFiltersForm(),
  footer: rodape,
  onOpenChange: (open) => sincronizarEstado(open),
});

customizationCode.web:
/* Largura do painel: declare as custom properties, não uma classe de largura.
   As regras de lado são (0,2,0) e nenhum utilitário (0,1,0) as vence — quem
   declara a custom property na mesma caixa ganha, venha de onde vier. */
.painel-largo {
  --sheet-width: 90%;
  --sheet-max-width: 33.75rem;
}

